cpp4m1.solucao:
#include <iostream>
using namespace std;

int main() {
    int preco, porSemana;
    cout << "Preço do jogo: ";
    cin >> preco;
    cout << "Quanto você guarda por semana? ";
    cin >> porSemana;

    int saldo = 0;
    int semana = 0;
    while (saldo < preco) {
        semana++;
        saldo += porSemana;
        cout << "Semana " << semana << ": R$ " << saldo << endl;
    }
    cout << "Na semana " << semana << " você já pode comprar o jogo!" << endl;
    return 0;
}

