cpp4m2.solucao:
#include <iostream>
using namespace std;

int main() {
    int partidas;
    cout << "Quantas partidas? ";
    cin >> partidas;

    int total = 0;
    int melhor = 0;
    for (int i = 1; i <= partidas; i++) {
        int pontos;
        cout << "Pontos da partida " << i << ": ";
        cin >> pontos;
        total += pontos;
        if (pontos > melhor) {
            melhor = pontos;
        }
    }
    cout << "Total: " << total << endl;
    cout << "Melhor partida: " << melhor << endl;
    return 0;
}

