    // repetindo até a opção 0

    return 0;
}

cpp4m3.solucao:
#include <iostream>
using namespace std;

int main() {
    int moedas = 20;
    int pocoes = 0;
    int opcao;
    do {
        cout << "[1] Bolsa [2] Trabalhar [3] Comprar poção [0] Sair" << endl;
        cout << "Opção: ";
        cin >> opcao;
        switch (opcao) {
            case 1:
                cout << "Moedas: " << moedas << " | Poções: " << pocoes << endl;
                break;
            case 2:
                moedas += 10;
                cout << "Você trabalhou e ganhou 10 moedas." << endl;
                break;
            case 3:
                if (moedas >= 15) {
                    moedas -= 15;
                    pocoes++;
                    cout << "Você comprou uma poção." << endl;
                } else {
                    cout << "Moedas insuficientes." << endl;
                }
                break;
            case 0:
                cout << "Até a próxima!" << endl;
                break;
            default:
                cout << "Opção inválida." << endl;
        }
    } while (opcao != 0);
    return 0;
}

