cpp4m4.solucao:
#include <iostream>
using namespace std;

int main() {
    int rodadas = 0;
    int total = 0;
    while (true) {
        int pontos;
        cout << "Pontos (0 para terminar): ";
        cin >> pontos;
        if (pontos == 0) {
            break;
        }
        if (pontos < 0) {
            cout << "Valor inválido, ignorado." << endl;
            continue;
        }
        rodadas++;
        total += pontos;
    }
    cout << "Rodadas válidas: " << rodadas << endl;
    cout << "Total: " << total << endl;
    return 0;
}

