    int linhas, colunas;
    cout << "Linhas: ";
    cin >> linhas;
    cout << "Colunas: ";
    cin >> colunas;

    for (int linha = 0; linha < linhas; linha++) {
        for (int coluna = 0; coluna < colunas; coluna++) {
            if ((linha + coluna) % 2 == 0) {
                cout << "#";
            } else {
