cpp4m6.solucao:
#include <iostream>
#include <cstdlib>
using namespace std;

int main() {
    int semente;
    cout << "Semente: ";
    cin >> semente;
    srand(semente);
    int secreto = rand() % 100 + 1;

    cout << "Pensei em um número de 1 a 100. Você tem 7 tentativas." << endl;
    int tentativas = 0;
    bool acertou = false;
    while (tentativas < 7) {
        int palpite;
        cout << "Tentativa " << tentativas + 1 << ": ";
        cin >> palpite;
        if (palpite < 1 || palpite > 100) {
            cout << "Fora do intervalo: digite de 1 a 100." << endl;
            continue;
        }
        tentativas++;
        if (palpite == secreto) {
            acertou = true;
            break;
        }
        if (palpite < secreto) {
            cout << "É maior." << endl;
        } else {
            cout << "É menor." << endl;
        }
    }

    if (acertou) {
        if (tentativas == 1) {
            cout << "Acertou de primeira!" << endl;
        } else {
            cout << "Acertou em " << tentativas << " tentativas!" << endl;
        }
    } else {
        cout << "Acabaram as tentativas. O número era " << secreto << "." << endl;
    }
    return 0;
}
